import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] orders = {"chai", "poha", "chai", "samosa", "chai", "poha"};
        Map<String, Integer> count = new HashMap<>();
        for (String item : orders) count.merge(item, 1, Integer::sum);   // add 1, or start at 1
        System.out.println("chai: " + count.get("chai") + ", idli: " + count.getOrDefault("idli", 0));
        System.out.println("sorted: " + new TreeMap<>(count));               // HashMap order is not defined
        count.computeIfPresent("poha", (k, v) -> v > 1 ? v - 1 : null);    // returning null removes the key
        System.out.println("after one poha cancelled: " + new TreeMap<>(count));
    }
}

