import java.util.*;

public class Main {
    static final class Seat {
        String coach;                       // NOT final: this is the bug
        int number;
        Seat(String coach, int number) { this.coach = coach; this.number = number; }
        @Override public boolean equals(Object o) {
            return o instanceof Seat s && s.number == number && s.coach.equals(coach);
        }
        @Override public int hashCode() { return Objects.hash(coach, number); }
    }

    public static void main(String[] args) {
        Map<Seat, String> booking = new HashMap<>();
        Seat s = new Seat("S1", 23);
        booking.put(s, "Aditi");
        System.out.println("before change: " + booking.get(new Seat("S1", 23)));
        s.coach = "S2";                     // mutate a key that is inside the map
        System.out.println("look up S2-23: " + booking.get(new Seat("S2", 23)));
        System.out.println("look up S1-23: " + booking.get(new Seat("S1", 23)));
        System.out.println("map size: " + booking.size());
    }
}

