import java.io.*;
import java.util.*;

public class Main {
    static Map<String, Integer> countAll(List<String> rolls) {
        Map<String, Integer> count = new HashMap<>();
        for (String r : rolls) count.merge(r, 1, Integer::sum);
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine().trim());
        List<String> rolls = new ArrayList<>();
        StringTokenizer st = new StringTokenizer(in.readLine());
        for (int i = 0; i < n; i++) rolls.add(st.nextToken());
        StringBuilder out = new StringBuilder();
        for (Map.Entry<String, Integer> e : new TreeMap<>(countAll(rolls)).entrySet())
            if (e.getValue() > 1) out.append(e.getKey()).append(' ').append(e.getValue()).append('\n');
        System.out.print(out.length() == 0 ? "none\n" : out.toString());
    }
}
